/* width.c -- 字段宽度 */
#include <stdio.h>
#define PAGES 959
int main(void)
{
printf("%d*\n", PAGES);
printf("%2d*\n", PAGES);
printf("%10d*\n", PAGES);
return 0;
printf("%-10d*\n", PAGES);
}

// floats.c -- 一些浮点型修饰符的组合
#include <stdio.h>

int main(void)
{
const double RENT = 3852.99; // const变量
printf("%f\n", RENT);
printf("%e\n", RENT);
printf("%4.2f\n", RENT);
printf("%3.1f\n", RENT);
printf("%10.3f\n", RENT);
printf("%10.3E\n", RENT);
printf("%+4.2f\n", RENT);

printf("%010.2f\n", RENT);

return 0;

}

